using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class PaulVerlaine
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Je fais souvent ce rêve étrange et pénétrant\nD'une femme inconnue, et que j'aime, et qui m'aime,\nEt qui n'est, chaque fois, ni tout à fait la même,\nNi tout à fait une autre, et m'aime et me comprend.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Et pour sa voix, lointaine, et calme, et grave, elle a\nL'inflexion des voix chères qui se sont tues.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "L’Océan sonore\nPalpite sous l’œil\nDe la lune en deuil", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Les sanglots longs\nDes violons\nDe l'automne\nBlessent mon cœur\nD'une langueur\nMonotone.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Et je m'en vais\nAu vent mauvais\nQui m'emporte\nDeçà, delà\nPareil à la\nFeuille morte.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Votre âme est un paysage choisi\nQue vont charmants masques et bergamasques\nJouant du luth et dansant et quasi\nTristes sous leurs déguisements fantasques.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Colombine rêve, surprise\nDe sentir un cœur dans la brise\nEt d’entendre en son cœur des voix.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Fardée et peinte comme au temps des bergeries,\nFrêle parmi les nœuds énormes de rubans,\nElle passe, sous les ramures assombries,\nDans l’allée où verdit la mousse des vieux bancs", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Trompeurs exquis et coquettes charmantes,\nCœurs tendres mais affranchis du serment,\nNous devisons délicieusement", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Le soir tombait, un soir équivoque d’automne :\nLes belles, se pendant rêveuses à nos bras,\nDirent alors des mots si spécieux, tout bas,\nQue notre âme depuis ce temps tremble et s’étonne.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Ce fut le temps, sous de clairs ciels,\n(Vous en souvenez-vous, Madame ?)\nDes baisers superficiels\nEt des sentiments à fleur d’âme", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Heureux instants ! — mais vint l’Été :\nAdieu, rafraîchissantes brises !\nUn vent de lourde volupté\nInvestit nos âmes surprises.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Scaramouche et Pulcinella\nQu’un mauvais dessein rassembla\nGesticulent, noirs sur la lune.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Un pavillon à claires-voies\nAbride doucement nos joies", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Et l’Amour comblant tout, hormis\nLa faim, sorbets et confitures\nNous préservent des courbatures.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Cependant la lune se lève\nEt l’esquif en sa course brève\nFile gaîment sur l’eau qui rêve.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Ferme tes yeux à demi,\nCroise tes bras sur ton sein,\nEt de ton cœur endormi\nChasse à jamais tout dessein.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "— Ton cœur bat-il toujours à mon seul nom ?\nToujours vois-tu mon âme en rêve ? — Non.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Il pleure dans mon cœur\nComme il pleut sur la ville,\nQuelle est cette langueur\nQui pénètre mon cœur ?", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Le ciel est, par-dessus le toit,\nSi bleu, si calme ! Un arbre, par-dessus le toit\nBerce sa palme.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Je ne sais pourquoi\nMon esprit amer\nD'une aile inquiète et folle vole sur la mer.\nTout ce qui m'est cher,\nD'une aile d'effroi\nMon amour le couve au ras des flots. Pourquoi, pourquoi ?", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "On sait trop tout le prix du malheur\nPour le perdre en disert gaspillage.\nVous n'aurez ni mes traits ni mon âge,\nNi le vrai mal secret de mon cœur.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Le bonheur de saigner sur le cœur d'un ami,\nLe besoin de pleurer bien longtemps sur son sein,\nLe désir de parler à lui, bas à demi,\nLe rêve de rester ensemble sans dessein !", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Mortel, ange et démon, autant dire Rimbaud,\nTu mérites la prime place en ce mien livre", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "À l’Escrime, le seul de nos maîtres sortable,\nRobert, nous démontrait quelque coup inouï\nD’audace magnifique ou de ruse admirable\nEt nous clamions à plein gosier : Ça c’est de Lui !", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Une inquiétude profonde\nM'agite en douloureux transports\nEntre le sublime et l'immonde :\n– Deux écueils, Seigneur, ou deux ports ?", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Je compare ces vers étranges\nAux étranges vers que ferait\nUn marquis de Sade discret\nQui saurait la langue des anges", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Quand même tu dirais\nQue tu me trahirais\nSi c'était ton caprice,\nQu’est-ce que me ferait\nCe terrible secret\nSi c’était mon caprice !", Author = "Paul Verlaine" },
        };
    }
}